import { useState } from 'react';
import { Link } from 'react-router-dom';
import { CalendarClock, MessageCircle } from 'lucide-react';
import { crmApi, messageFromError } from '../api';
import { useDebouncedValue, useResource } from '../hooks';
import { crmPath, formatDate, today } from '../constants';
import { Button, Card, ErrorState, Field, Input, Loading, MessagePreview, PageHeader, SearchBox, Select, Status, Table } from '../components/ui';
export default function Expiries(){const[from,setFrom]=useState(today());const[days,setDays]=useState('30');const[q,setQ]=useState('');const[error,setError]=useState('');const[reminder,setReminder]=useState(null);const dq=useDebouncedValue(q);const r=useResource(()=>`/reports/expiries?pageSize=200&from=${from}&days=${days}&search=${encodeURIComponent(dq)}`,[from,days,dq]);const remind=async row=>{try{const response=await crmApi.post('/operations/reminders/prepare',{reminderType:'expiry',entityType:'sale_item',entityId:row.id});setReminder(response.data)}catch(e){setError(messageFromError(e))}};const sendReminder=async url=>{window.open(url,'_blank','noopener,noreferrer');try{await crmApi.post(`/operations/reminders/${reminder.id}/opened`,{})}catch{/* best effort */}setReminder(null)};if(r.initialLoading)return <Loading/>;if(r.error)return <ErrorState message={r.error} onRetry={r.reload}/>;return <><PageHeader title="Expiry & renewal alerts" description="Subscription expiries with one-click, pre-filled WhatsApp renewal messages."/>{error&&<div className="bcrm-banner warning">{error}</div>}<div className="bcrm-filterbar"><Field label="From"><Input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></Field><Field label="Window"><Select value={days} onChange={e=>setDays(e.target.value)}><option value="7">7 days</option><option value="30">30 days</option><option value="60">60 days</option><option value="90">90 days</option></Select></Field><SearchBox value={q} onChange={setQ} busy={r.loading} placeholder="Client, product or invoice…"/></div><Card className="flush" title={`${r.data?.total??r.data?.rows?.length??0} expiring access records`}><Table rows={r.data?.rows||[]} columns={[{key:'expiry_date',label:'Expiry',render:x=>formatDate(x.expiry_date)},{key:'days_remaining',label:'Days',render:x=><Status tone={Number(x.days_remaining)<=3?'danger':Number(x.days_remaining)<=7?'warning':'info'}>{x.days_remaining} days</Status>},{key:'name',label:'Product'},{key:'client_name',label:'Client'},{key:'invoice_number',label:'Invoice',render:x=><Link to={crmPath(`sales/${x.sale_id}`)}>{x.invoice_number}</Link>},{key:'contact',label:'Reminder',render:x=><Button variant="ghost" icon={MessageCircle} onClick={()=>remind(x)}>Prepare</Button>}]} /></Card><MessagePreview open={Boolean(reminder)} title="Renewal reminder preview" message={reminder?.message} recipient={reminder?.recipient} url={reminder?.url} onClose={()=>setReminder(null)} onSend={sendReminder}/></>}
